def manage_bank_account():
    """Manage a bank account with loans based on user input."""

    # Initialize loan limit and loan amount
    loan_limit = 10000
    loan_amount = 0

    while True:
        user_input = input("Apply loan [{}]: ".format(loan_amount)).lower()

        if user_input == "apply loan":
            # Get loan amount from user
            loan_amount = int(input("Enter loan amount: "))

            # Check if loan amount is within loan limit
            if loan_amount <= loan_limit:
                print("Loan approved")
            else:
                print("Loan rejected (amount exceeds loan limit)")

        elif user_input == "quit":
            print("Exiting the program...")
            break

        else:
            print("Invalid input. Please try again.")


if __name__ == "__main__":
    manage_bank_account()
